def extract_end_bits(num_end_bits, pixel):
    # The last k bits of an integer n are exactly n % (2**k).
    mask = 2 ** num_end_bits
    if isinstance(pixel, tuple):
        return tuple(value % mask for value in pixel)
    return pixel % mask

