from PIL import Image
import numpy

def make_matrix(color):
    if color == 'red':
        c = [[.567, .433, 0], [.558, .442, 0], [0, .242, .758]]
    elif color == 'green':
        c = [[0.625, 0.375, 0], [0.7, 0.3, 0], [0, 0.142, 0.858]]
    elif color == 'blue':
        c = [[.95, 0.05, 0], [0, 0.433, 0.567], [0, 0.475, .525]]
    elif color == 'none':
        c = [[1, 0., 0], [0, 1, 0.], [0, 0., 1]]
    return c

def matrix_multiply(m1, m2):
    product = numpy.matmul(m1, m2)
    if type(product) == numpy.int64:
        return float(product)
    else:
        result = list(product)
        return result

def filter(pixels_list, color):
    matrix = make_matrix(color)
    result = []
    for pixel in pixels_list:
        transformed = matrix_multiply(matrix, list(pixel))
        result.append(tuple(int(channel) for channel in transformed))
    return result

