from PIL import Image

def extract_end_bits(num_end_bits, pixel):
    mask = 2 ** num_end_bits
    if isinstance(pixel, tuple):
        return tuple(v % mask for v in pixel)
    return pixel % mask

def img_to_pix(filename):
    return list(Image.open(filename).getdata())

def pix_to_img(pixels_list, size, mode):
    img = Image.new(mode, size)
    img.putdata(pixels_list)
    return img

def reveal_color_image(filename):
    im = Image.open(filename)
    size = im.size
    pixels = img_to_pix(filename)
    # 3 LSBs give 0..7 per channel; scale by 32 to spread across 0..224.
    revealed = [tuple(channel * 32 for channel in extract_end_bits(3, p)) for p in pixels]
    return pix_to_img(revealed, size, 'RGB')
